"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[5760],{75760:a=>{a.exports=JSON.parse('{"meta":{"title":"Niyyah: convierte una intenci\xf3n en un paso peque\xf1o y constante - iMuslim Life","description":"Niyyah convierte una intenci\xf3n en un plan de 7 d\xedas ligado a tus horarios de oraci\xf3n, y Ecos del Cor\xe1n encuentra pasajes del Cor\xe1n revisados por sabios para lo que llevas en el coraz\xf3n. Gratis y sin anuncios."},"periods":{"fajr":"Fajr","dhuhr":"Dhuhr","asr":"Asr","maghrib":"Maghrib","isha":"Isha"},"hero":{"eyebrow":"Niyyah","h1":"Convierte una intenci\xf3n en un paso <g>peque\xf1o y constante</g>.","lede":"Cinco preguntas amables se convierten en un plan de siete d\xedas entretejido con las oraciones que ya haces. Y cuando tu coraz\xf3n pesa, Ecos del Cor\xe1n encuentra las aleyas que le hablan.","begin":"Empezar, bismillah","tryEchoes":"Probar Ecos del Cor\xe1n","facts":"Gratis \xb7 Sin anuncios \xb7 Revisado por sabios \xb7 Funciona en tu navegador","scroll":"Desliza: un d\xeda, de Fajr a Isha","alt":"Niyyah: un mihrab con la Basmala bajo el cielo nocturno"},"hadith":{"text":"\xabLas acciones solo valen por las intenciones\xbb.","src":"Sahih al-Bujari 1 \xb7 Sahih Muslim 1907"},"steps":[{"t":"Intenci\xf3n","d":"Elige en qu\xe9 quieres crecer: paciencia, cercan\xeda al Cor\xe1n, gratitud, dulzura en casa."},{"t":"Acci\xf3n","d":"Un paso peque\xf1o de dos a quince minutos. Lo bastante peque\xf1o para mantenerlo en tu d\xeda m\xe1s dif\xedcil."},{"t":"Momento","d":"Ligado a una oraci\xf3n que ya haces, a tus propios horarios, as\xed cambia con las estaciones."},{"t":"Reflexi\xf3n","d":"Un repaso amable el tercer y el s\xe9ptimo d\xeda. \xbfMala hora? \xbfDemasiado? Se ajusta en segundos."}],"effortNote":"Completar una rutina es esfuerzo por nuestra parte. La aceptaci\xf3n y los frutos pertenecen a Allah. El plan es una herramienta, no una medida de tu fe.","try":{"eyebrow":"Ecos del Cor\xe1n \xb7 pru\xe9balo ahora","h2":"\xbfQu\xe9 llevas en el <e>coraz\xf3n</e>?","lede":"Escribe una l\xednea sobre lo que est\xe1s viviendo, en ingl\xe9s, urdu, urdu romanizado o \xe1rabe. Niyyah responde con un pasaje de un \xedndice revisado por sabios y una pregunta para meditar. Sin registro. Nada de lo que escribes se guarda.","inputLabel":"Describe tu situaci\xf3n","listening":"Escuchando\u2026","find":"Buscar pasajes","failed":"No se pudo contactar con Ecos del Cor\xe1n ahora. Est\xe1 en <a>alexa.imuslimlife.com/niyyah</a>, int\xe9ntalo all\xed.","crisisH":"Por favor, habla con alguien ahora.","crisisP":"Lo que describes parece grave, y mereces el apoyo real de una persona.","rulingEyebrow":"Esto necesita a un sabio","rulingH":"Las preguntas sobre normas religiosas necesitan a una persona cualificada.","rulingP":"Niyyah nunca da fatwas. Un imam que conozca tu situaci\xf3n podr\xe1 responderte bien.","none":"A\xfan no hay una coincidencia cercana. Prueba con algunas palabras m\xe1s sobre c\xf3mo te sientes o lo que vives.","surah":"Sura","tafsir":"Tafsir","plan":"Convertirlo en un plan de 7 d\xedas","missThanks":"Gracias, nos ayuda a mejorar. Prueba a describirlo con otras palabras.","miss":"No es lo que quer\xeda decir","shared":"Compartido, gracias. Ayuda a mejorar Ecos del Cor\xe1n.","share":"Comparte esta pregunta (sin tu nombre) para ayudar a mejorar Ecos del Cor\xe1n.","example":"Un ejemplo","exampleQ":"\xbfCu\xe1ndo fue la \xfaltima vez que el recuerdo de Allah te dio calma?","exampleSrc":"Ar-Ra\u2019d 13:28 \xb7 Traducci\xf3n del significado: Julio Cort\xe9s. \xc1rabe: Tanzil Uthmani.","examples":["I keep losing my temper with my kids","mujhe bohat ghussa aata hai","I feel guilty, will Allah forgive me?","My father passed away and it feels heavy","I\u2019m anxious about money and the future"],"placeholder":"For example: I get impatient with my children in the evenings"},"ayah":{"en":"Quienes crean, aqu\xe9llos cuyos corazones se tranquilicen con el recuerdo de Al\xe1 -\xbfc\xf3mo no van a tranquilizarse los corazones con el recuerdo de Al\xe1?-,","src":"Ar-Ra\u2019d 13:28 \xb7 Traducci\xf3n del significado: Julio Cort\xe9s"},"week":{"eyebrow":"Tu semana","h2":"Cada d\xeda que te presentas, <e>se abre una rosa</e>.","lede":"Sin rachas que romper, sin culpa. Los d\xedas perdidos se quedan como capullos cerrados y el plan sigue ma\xf1ana. El cielo cambia con tus horarios de oraci\xf3n, del rosa de Fajr a las estrellas de Isha.","label":"Una semana de rosas: cinco d\xedas abiertos","shots":["Hoy, en Isha","Tu plan de 7 d\xedas","El mismo d\xeda, en Dhuhr"]},"care":{"eyebrow":"Hecho con cuidado","h2":"Fiable <e>por dise\xf1o</e>.","items":[{"t":"Revisado por sabios","d":"Cada pasaje, peque\xf1a acci\xf3n y pregunta se revisa y aprueba antes de que nadie lo vea."},{"t":"Nunca una fatwa","d":"Las preguntas sobre normas se remiten con delicadeza a un sabio cualificado. Niyyah nunca dictamina."},{"t":"Nada inventado","d":"Aqu\xed ninguna IA escribe texto religioso. Los pasajes son el propio Cor\xe1n, con una traducci\xf3n identificada."},{"t":"Seguro","d":"Las palabras sobre da\xf1o o peligro muestran primero l\xedneas de ayuda, nunca pasajes."},{"t":"Privado","d":"Tus notas son solo tuyas. B\xf3rralo todo con un toque."},{"t":"Gratis, para siempre","d":"Sin anuncios ni suscripciones. Sadaqa yariya, in sh\u0101\u02be All\u0101h."}]},"faq":{"eyebrow":"Preguntas","h2":"Bueno <e>saberlo</e>.","items":[{"q":"\xbfQu\xe9 significa \xabNiyyah\xbb?","a":"Niyyah (\u0646\u0650\u064a\u064e\u0651\u0629) es la intenci\xf3n. \xabLas acciones solo valen por las intenciones\xbb (Sahih al-Bujari 1). Niyyah ayuda a que una intenci\xf3n se convierta en una acci\xf3n peque\xf1a y constante."},{"q":"\xbfNecesito una cuenta?","a":"No hace falta cuenta para probar Ecos del Cor\xe1n. Para guardar un plan, marcar los d\xedas que cumpliste y guardar pasajes, inicia sesi\xf3n con Amazon, la misma cuenta que Muslim Companion for Alexa."},{"q":"\xbfQu\xe9 idiomas entiende?","a":"Ingl\xe9s, urdu, urdu romanizado (como \xabmujhe bohat ghussa aata hai\xbb) y \xe1rabe. Los pasajes muestran el \xe1rabe con una traducci\xf3n al ingl\xe9s o al urdu."},{"q":"\xbfSustituye a un sabio o a un consejero?","a":"No. Niyyah ofrece pasajes para reflexionar y pasos peque\xf1os. Para normas religiosas, consulta a un sabio cualificado; en momentos dif\xedciles, acude a alguien de confianza o a una l\xednea de ayuda."},{"q":"\xbfD\xf3nde funciona?","a":"En cualquier navegador de tu m\xf3vil, tableta u ordenador, en alexa.imuslimlife.com/niyyah."}]},"final":{"h2":"Empieza con un paso <g>peque\xf1o</g>.","lede":"Tu primer plan lleva un minuto. Que Allah te lo facilite y te lo acepte.","alexa":"Muslim Companion for Alexa"}}')}}]);